/**
 * Errors that can occur across the ClipBridge FFI boundary.
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Crypto(msg: String
    )
    case Decode(msg: String
    )
    case PayloadTooLarge(size: UInt64, max: UInt64
    )
    case GroupMismatch
    case HashMismatch
    case Storage(msg: String
    )
    case Image(msg: String
    )
    case InvalidPairingUri(msg: String
    )
    case Relay(msg: String
    )
    case Io(msg: String
    )
    case Serialization(msg: String
    )
    case Generic(msg: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Crypto(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Decode(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .PayloadTooLarge(
            size: try FfiConverterUInt64.read(from: &buf), 
            max: try FfiConverterUInt64.read(from: &buf)
            )
        case 4: return .GroupMismatch
        case 5: return .HashMismatch
        case 6: return .Storage(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Image(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 8: return .InvalidPairingUri(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Relay(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Io(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 11: return .Serialization(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Generic(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Crypto(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Decode(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .PayloadTooLarge(size,max):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(size, into: &buf)
            FfiConverterUInt64.write(max, into: &buf)
            
        
        case .GroupMismatch:
            writeInt(&buf, Int32(4))
        
        
        case .HashMismatch:
            writeInt(&buf, Int32(5))
        
        
        case let .Storage(msg):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Image(msg):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .InvalidPairingUri(msg):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Relay(msg):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Io(msg):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Serialization(msg):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Generic(msg):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


